  const NEXT_URL = 'http://localhost:3000/api/moodle';
  console.log('Testing AuraHR Unified Auth Flow via Next.js Proxy...');

  // Step 1: Attempt Signup
  try {
    console.log('\n[1/2] Testing Signup...');
    const signupRes = await fetch(NEXT_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'signup',
        username: 'testcandidate',
        password: 'Password123#',
        firstname: 'Test',
        lastname: 'Candidate',
        email: 'testcandidate@example.com',
        role: 'candidate'
      })
    });
    const signupData = await signupRes.json();
    console.log('Signup Status:', signupRes.status, signupRes.statusText);
    console.log('Signup Response:', JSON.stringify(signupData, null, 2));
  } catch (e) {
    console.error('Signup Error:', e);
  }

  // Step 2: Attempt Login
  try {
    console.log('\n[2/2] Testing Login...');
    const loginRes = await fetch(NEXT_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'login',
        username: 'testcandidate',
        password: 'Password123#'
      })
    });
    const loginData = await loginRes.json();
    console.log('Login Status:', loginRes.status, loginRes.statusText);
    console.log('Login Response:', JSON.stringify(loginData, null, 2));
  } catch (e) {
    console.error('Login Error:', e);
  }
}
test();
