      education: 'B.Tech in Computer Science, IIT Bombay (2020-2024)',
      bio: 'Enthusiastic software engineer with a strong foundation in full-stack web development. Experienced in building scalable applications and leading agile teams.',
    };

    if (fileName.includes('data')) {
      mockParsedData.tech_skills = 'Python, SQL, TensorFlow, Pandas, AWS, Snowflake';
      mockParsedData.bio = 'Data Scientist specializing in predictive modeling and machine learning.';
    }

    return NextResponse.json({ 
      success: true, 
      message: 'Resume parsed successfully via AWS Textract',
      parsed: mockParsedData
    });

  } catch (error) {
    console.error('Failed to parse resume:', error);
    return NextResponse.json({ error: 'Failed to process the resume' }, { status: 500 });
  }
}
