namespace local_aurahr_jobs\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;

/**
 * Candidate submits answers to an academia assessment.
 * Backend calculates score as (correct / total) * 100, stores it,
 * and updates the application stage to 'academia'.
 */
class submit_assessment extends external_api {

    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'assessmentid' => new external_value(PARAM_INT, 'Assessment ID'),
            'answers'      => new external_value(PARAM_RAW, 'JSON: [{questionid, answer}...]'),
        ]);
    }

    public static function execute(int $assessmentid, string $answers): array {
        global $DB, $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'assessmentid' => $assessmentid, 'answers' => $answers,
        ]);

        $context = \context_system::instance();
        self::validate_context($context);

        $assessment = $DB->get_record('local_aurahr_assessments',
            ['id' => $params['assessmentid']], '*', MUST_EXIST);

        // Verify candidate has an application for this job.
        $application = $DB->get_record('local_aurahr_applications',
            ['jobid' => $assessment->jobid, 'userid' => $USER->id], '*', MUST_EXIST);

        // Parse questions and answers.
        $questions = json_decode($assessment->questions, true) ?: [];
        $submitted = json_decode($params['answers'], true) ?: [];

        // Build answer map {questionid -> answer}.
        $answerMap = [];
        foreach ($submitted as $a) {
            if (isset($a['questionid'])) {
                $answerMap[$a['questionid']] = $a['answer'] ?? '';
            }
        }

        // Score: each question has a 'correct_answer' field.
        $correct = 0;
        $total   = count($questions);

        foreach ($questions as $q) {
            $qid = $q['id'] ?? $q['questionid'] ?? null;
            if ($qid === null) continue;
            $candidateAns = strtolower(trim($answerMap[$qid] ?? ''));
            $correctAns   = strtolower(trim($q['correct_answer'] ?? ''));
            if ($candidateAns !== '' && $candidateAns === $correctAns) {
                $correct++;
            }
        }

        $score = $total > 0 ? round(($correct / $total) * 100, 2) : 0.0;

        // Update application.
        $now = time();
        $application->academia_score = $score;
        $application->stage          = 'academia';
        $application->overall_score  = round(
            (((float)$application->jd_score ?? 0) * 0.4 + $score * 0.6), 2
        );
        $application->timemodified   = $now;
        $DB->update_record('local_aurahr_applications', $application);

        return [
            'success'  => true,
            'score'    => $score,
            'correct'  => $correct,
            'total'    => $total,
            'stage'    => $application->stage,
            'message'  => "You scored {$score}% ({$correct}/{$total} correct).",
        ];
    }

    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'success' => new external_value(PARAM_BOOL,  'Success'),
            'score'   => new external_value(PARAM_FLOAT, 'Percentage score'),
            'correct' => new external_value(PARAM_INT,   'Correct answers'),
            'total'   => new external_value(PARAM_INT,   'Total questions'),
            'stage'   => new external_value(PARAM_TEXT,  'New application stage'),
            'message' => new external_value(PARAM_TEXT,  'Human-readable result'),
        ]);
    }
}

