namespace local_aurahr_jobs\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;

/**
 * Schedule an academia assessment for a job.
 * Org creates the test with questions (JSON array), start/end time, and pass count.
 */
class schedule_assessment extends external_api {

    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'jobid'        => new external_value(PARAM_INT,  'Job ID'),
            'title'        => new external_value(PARAM_TEXT, 'Assessment title'),
            'questions'    => new external_value(PARAM_RAW,  'JSON array of question objects'),
            'num_questions'=> new external_value(PARAM_INT,  'Number of questions', VALUE_DEFAULT, 10),
            'pass_count'   => new external_value(PARAM_INT,  'No. of candidates to pass', VALUE_DEFAULT, 0),
            'start_time'   => new external_value(PARAM_INT,  'Start timestamp (unix)', VALUE_DEFAULT, 0),
            'end_time'     => new external_value(PARAM_INT,  'End timestamp (unix)',   VALUE_DEFAULT, 0),
        ]);
    }

    public static function execute(
        int $jobid, string $title, string $questions,
        int $num_questions, int $pass_count, int $start_time, int $end_time
    ): array {
        global $DB;

        $params = self::validate_parameters(self::execute_parameters(), [
            'jobid' => $jobid, 'title' => $title, 'questions' => $questions,
            'num_questions' => $num_questions, 'pass_count' => $pass_count,
            'start_time' => $start_time, 'end_time' => $end_time,
        ]);

        $context = \context_system::instance();
        require_capability('local/aurahr_jobs:managejobs', $context);

        // Validate job exists.
        $DB->get_record('local_aurahr_jobs', ['id' => $params['jobid']], '*', MUST_EXIST);

        $now = time();

        // Upsert: delete old assessment for this job, create new one.
        $DB->delete_records('local_aurahr_assessments', ['jobid' => $params['jobid']]);

        $record = (object)[
            'jobid'         => $params['jobid'],
            'title'         => $params['title'],
            'questions'     => $params['questions'],
            'num_questions' => $params['num_questions'],
            'pass_count'    => $params['pass_count'],
            'start_time'    => $params['start_time'],
            'end_time'      => $params['end_time'],
            'status'        => 'scheduled',
            'timecreated'   => $now,
        ];

        $id = $DB->insert_record('local_aurahr_assessments', $record);

        return [
            'id'          => (int)$id,
            'jobid'       => (int)$params['jobid'],
            'status'      => 'scheduled',
            'start_time'  => (int)$params['start_time'],
            'end_time'    => (int)$params['end_time'],
            'success'     => true,
        ];
    }

    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'id'         => new external_value(PARAM_INT,  'Assessment ID'),
            'jobid'      => new external_value(PARAM_INT,  'Job ID'),
            'status'     => new external_value(PARAM_TEXT, 'Status'),
            'start_time' => new external_value(PARAM_INT,  'Start time unix'),
            'end_time'   => new external_value(PARAM_INT,  'End time unix'),
            'success'    => new external_value(PARAM_BOOL, 'Success flag'),
        ]);
    }
}

