class get_calendar extends external_api {

    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'start_time' => new external_value(PARAM_INT, 'Range start unix timestamp'),
            'end_time'   => new external_value(PARAM_INT, 'Range end unix timestamp'),
        ]);
    }

    public static function execute(int $start_time, int $end_time): array {
        global $DB;

        $params = self::validate_parameters(self::execute_parameters(), [
            'start_time' => $start_time, 'end_time' => $end_time,
        ]);
        $context = \context_system::instance();
        require_capability('local/aurahr_jobs:viewapplications', $context);

        $sql = "SELECT i.*, u.firstname, u.lastname, j.title as job_title
