"        // Fetch real calendar events for the next 30 days
        const now = Math.floor(Date.now() / 1000);
        const nextMonth = now + 30 * 24 * 60 * 60;
        const calRes = await moodleCall<{events: any[]}>('local_aurahr_jobs_get_calendar', { start_time: now - 86400, end_time: nextMonth }).catch(() => ({ events: [] }));

        // Map real scheduled interviews from calendar
        const scheduled = apps.map(app => {
          const evt = calRes.events?.find(e => e.applicationid === app.id);
          if (!evt) return null;

          const scheduledDate = new Date(evt.scheduled_at * 1000);
          const isLive = Math.abs(Date.now() - scheduledDate.getTime()) < 60 * 60 * 1000; // Live if within 1 hour

          return {
            id: app.id,
            name: `${app.firstname} ${app.lastname}`,
            date: scheduledDate.toLocaleString('en-IN', { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }),
            role: 'Candidate',
            live: isLive,
            scheduled_at: evt.scheduled_at
          };
        }).filter(Boolean).sort((a: any, b: any) => a.scheduled_at - b.scheduled_at);

        setScheduledInterviews(scheduled);

        const evals = apps.map(app => ({
          id: app.id,
          name: `${app.firstname} ${app.lastname}`,
          interviewScore: app.interview_score || 0,
          overallScore: app.overall_score || 0,
          malpractice: app.malpractice === 1,
          status: app.stage === 'selected' || app.stage === 'rejected' ? app.stage : 'pending'
        }));
        setEvalCandidates(evals);
      } catch (err) {
        console.error('Failed to load interview candidates:', err);
      } finally {
        setLoadingData(false);
      }
    }
    fetchCandidates();
  }, [jobId]);"

