"  async function handleApply(jobId: number) {
    setApplying(jobId);
    try {
      const applyRes = await moodleCall<{id: number, success: boolean}>('local_aurahr_jobs_apply', { jobid: jobId });
      setApplied(prev => new Set(prev).add(jobId));

      if (applyRes && applyRes.id) {
        // Fire and forget social profile analysis in the background
        fetch('/api/socials/analyze', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ applicationid: applyRes.id })
        }).catch(err => console.error('Failed to trigger background analysis:', err));
      }

    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Apply failed';
      alert(msg);
    } finally {
      setApplying(null);
    }
  }"

