"import React from 'react';
import { Clock } from 'lucide-react';

interface AssessmentHeaderProps {
  timeLeft: number;
  violationCount: number;
  flagged: boolean;
}

export function AssessmentHeader({ timeLeft, violationCount, flagged }: AssessmentHeaderProps) {
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const bgClass = flagged ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700';

  return (
    <header className="sticky top-0 z-10 flex items-center justify-between px-6 py-4 bg-white/80 backdrop-blur-lg border-b border-ink/10 rounded-b-xl shadow-sm">
      <div className="flex items-center gap-2 text-xl font-semibold text-ink">
        <Clock size={20} className="text-ink/70" />
        <span>{formatTime(timeLeft)}</span>
      </div>
      {violationCount > 0 && (
        <div className={`flex items-center gap-1 px-3 py-1 rounded-md text-sm font-medium ${bgClass}`}> 
          <span className="font-bold">{violationCount}</span>
          <span>Violation{violationCount !== 1 ? 's' : ''}</span>
        </div>
      )}
    </header>
  );
}
"

